data class DietFoodItem(
    val id: Int,
    val name: String,
    val description: String? = null,
    val imageRes: Int,
    val calories: Int,
    val protein: Int,
    val isVeg: Boolean = true,
    val category: String = "Chicken"
)
// SetSaver for saving Set<Int> in rememberSaveable
val SetSaver = Saver<Set<Int>, List<Int>>(
    save = { it.toList() },
    restore = { it.toSet() }
)

@Composable
fun CategoryDietTabsFood(
    navController: NavHostController? = null,
    currentSelectedIndex: Int,
    selectedDietTabIndex: Int,
    onCategorySelected: (DietCategoryPage) -> Unit = {},
    onTabIndexChanged: (Int) -> Unit = {},
    modifier: Modifier = Modifier
) {
    val TAG = "CategoryDietTabsFood"
    val initialVisibleCount = 8

    // All diet category pages
    val allDietCategoryPages = remember {
        listOf(
            DietCategoryPage.Chicken,
            DietCategoryPage.Salad,
            DietCategoryPage.Mutton,
            DietCategoryPage.Kebabs,
            DietCategoryPage.HealthySnacks,
            DietCategoryPage.LowCalorie,
            DietCategoryPage.Vegan,
            DietCategoryPage.ProteinRich,
            DietCategoryPage.Dessert,
            DietCategoryPage.VegMeal,
            DietCategoryPage.Bowl,
            DietCategoryPage.Sweets,
            DietCategoryPage.Khichdi,
            DietCategoryPage.Sundae,
            DietCategoryPage.Juice,
            DietCategoryPage.Lassi,
            DietCategoryPage.CurdRice,
            DietCategoryPage.Pudding,
            DietCategoryPage.Custard,  // This is index 18
            DietCategoryPage.Soup,
            DietCategoryPage.Brownie,
            DietCategoryPage.Waffles,
            DietCategoryPage.ColdCoffee,
            DietCategoryPage.GrilledChicken,
            DietCategoryPage.SteamedFish,
            DietCategoryPage.QuinoaBowl,
            DietCategoryPage.AvocadoToast,
            DietCategoryPage.GreenSmoothie,
            DietCategoryPage.Oatmeal,
            DietCategoryPage.GreekYogurt,
            DietCategoryPage.EggWhiteOmelette,
            DietCategoryPage.TunaSalad,
            DietCategoryPage.LentilSoup,
            DietCategoryPage.CottageCheese,
            DietCategoryPage.SproutsSalad,
            DietCategoryPage.BrownRiceBowl,
            DietCategoryPage.SteamedVeggies,
            DietCategoryPage.FruitBowl,
            DietCategoryPage.DetoxWater,
            DietCategoryPage.HerbalTea,
            DietCategoryPage.ProteinBar,
            DietCategoryPage.BoiledEggs,
            DietCategoryPage.HummusPlate,
            DietCategoryPage.SushiRolls,
            DietCategoryPage.TofuStirFry,
            DietCategoryPage.ChiaPudding,
            DietCategoryPage.MilletBowl,
        )
    }

    // Internal state
    var internalSelectedIndex by rememberSaveable {
        mutableIntStateOf(
            navController?.currentBackStackEntry?.savedStateHandle?.get<Int>("currentDietSelectedIndex")
                ?: selectedDietTabIndex
        )
    }

    var recentlySelectedTabs by rememberSaveable(stateSaver = SetSaver) {
        mutableStateOf(
            navController?.currentBackStackEntry?.savedStateHandle?.get<Set<Int>>("recentlySelectedDietTabs")
                ?: emptySet()
        )
    }

    // Save state
    LaunchedEffect(internalSelectedIndex) {
        navController?.currentBackStackEntry?.savedStateHandle?.set(
            "currentDietSelectedIndex",
            internalSelectedIndex
        )
    }

    LaunchedEffect(recentlySelectedTabs) {
        navController?.currentBackStackEntry?.savedStateHandle?.set(
            "recentlySelectedDietTabs",
            recentlySelectedTabs
        )
    }

    // Update when parent changes
    LaunchedEffect(selectedDietTabIndex) {
        if (selectedDietTabIndex != internalSelectedIndex) {
            Log.d(TAG, "External selectedDietTabIndex changed: $selectedDietTabIndex")
            internalSelectedIndex = selectedDietTabIndex

            // Also add to recently selected if needed
            if (selectedDietTabIndex >= initialVisibleCount) {
                recentlySelectedTabs = recentlySelectedTabs + selectedDietTabIndex
                Log.d(TAG, "Added to recentlySelectedTabs from external: $selectedDietTabIndex")
            }
        }
    }

    // Handle selection from See All page
    DisposableEffect(navController) {
        val savedStateHandle = navController?.currentBackStackEntry?.savedStateHandle

        // Listen for both the direct key and the updated index
        val liveData1 = savedStateHandle?.getLiveData<Int>("selectedDietTabFromSeeAll")
        val liveData2 = navController?.previousBackStackEntry?.savedStateHandle?.getLiveData<Int>("selectedDietTabFromSeeAll")

        val observer = androidx.lifecycle.Observer<Int> { newIndex ->
            if (newIndex != null && newIndex != internalSelectedIndex) {
                Log.d(TAG, "Received new index from See All: $newIndex")

                // Add to recently selected tabs if beyond first 8
                if (newIndex >= initialVisibleCount) {
                    val updatedSet = recentlySelectedTabs + newIndex
                    recentlySelectedTabs = updatedSet
                    Log.d(TAG, "Added to recentlySelectedTabs: $newIndex, now has ${updatedSet.size} items")
                    Log.d(TAG, "Recently selected tabs: $recentlySelectedTabs")
                }

                // Update the selected index
                internalSelectedIndex = newIndex

                // Notify parent
                onTabIndexChanged(newIndex)

                // Get the category page and call onCategorySelected
                allDietCategoryPages.getOrNull(newIndex)?.let { page ->
                    onCategorySelected(page)
                    Log.d(TAG, "Selected category: ${page.title}")
                }

                // Clear the values
                navController?.currentBackStackEntry?.savedStateHandle?.remove<Int>("selectedDietTabFromSeeAll")
                navController?.previousBackStackEntry?.savedStateHandle?.remove<Int>("selectedDietTabFromSeeAll")
            }
        }

        liveData1?.observeForever(observer)
        liveData2?.observeForever(observer)

        onDispose {
            liveData1?.removeObserver(observer)
            liveData2?.removeObserver(observer)
        }
    }

    // Build visible tabs - recomputes whenever recentlySelectedTabs changes
    val visibleTabs = remember(recentlySelectedTabs, internalSelectedIndex) {
        buildList {
            // Add first 8 tabs
            addAll(allDietCategoryPages.take(initialVisibleCount))

            Log.d(TAG, "Building visibleTabs - Recently selected: $recentlySelectedTabs")

            // Add recently selected tabs beyond first 8, preserving order
            // Convert to list and sort to maintain consistent order
            val sortedRecentTabs = recentlySelectedTabs
                .filter { it >= initialVisibleCount }
                .sorted()

            Log.d(TAG, "Sorted recent tabs: $sortedRecentTabs")

            sortedRecentTabs.forEach { index ->
                allDietCategoryPages.getOrNull(index)?.let {
                    add(it)
                    Log.d(TAG, "Added recent tab at index $index: ${it.title}")
                }
            }

            // Add See All tab at the end
            add(DietCategoryPage.SeeAll)
        }
    }

    // Create mapping from all indices to visible indices
    val allToVisibleMap = remember(recentlySelectedTabs) {
        val map = mutableMapOf<Int, Int>()

        // Map first 8 tabs
        for (i in 0 until minOf(initialVisibleCount, allDietCategoryPages.size)) {
            map[i] = i
        }

        // Map recent tabs
        val sortedRecentTabs = recentlySelectedTabs
            .filter { it >= initialVisibleCount }
            .sorted()

        sortedRecentTabs.forEachIndexed { index, allIndex ->
            map[allIndex] = initialVisibleCount + index
        }

        map
    }

    // Create reverse mapping from visible index to original index
    val visibleToAllMap = remember(recentlySelectedTabs) {
        val map = mutableMapOf<Int, Int>()

        // Map first 8 tabs
        for (i in 0 until minOf(initialVisibleCount, allDietCategoryPages.size)) {
            map[i] = i
        }

        // Map recent tabs
        val sortedRecentTabs = recentlySelectedTabs
            .filter { it >= initialVisibleCount }
            .sorted()

        sortedRecentTabs.forEachIndexed { index, allIndex ->
            map[initialVisibleCount + index] = allIndex
        }

        map
    }

    // Get visible index for current selection
    val selectedVisibleIndex = remember(internalSelectedIndex, recentlySelectedTabs, visibleTabs) {
        val visibleIndex = when {
            // Case 1: Selected index is within first 8 tabs
            internalSelectedIndex < initialVisibleCount -> internalSelectedIndex

            // Case 2: Selected index is a recently selected tab (beyond first 8)
            internalSelectedIndex in allToVisibleMap -> {
                val index = allToVisibleMap[internalSelectedIndex] ?: (visibleTabs.size - 1)
                Log.d(TAG, "Mapping internal index $internalSelectedIndex to visible index $index")
                index
            }

            // Case 3: Selected index is not in visible tabs - this shouldn't happen now
            else -> {
                Log.d(TAG, "WARNING: Selected index $internalSelectedIndex not found in visible tabs")
                // Force add to recently selected
                if (internalSelectedIndex >= initialVisibleCount) {
                    recentlySelectedTabs = recentlySelectedTabs + internalSelectedIndex
                }
                visibleTabs.size - 1 // Default to See All
            }
        }

        // Ensure the visible index is within bounds
        if (visibleIndex in visibleTabs.indices) {
            visibleIndex
        } else {
            Log.d(TAG, "Visible index $visibleIndex out of bounds, defaulting to See All")
            visibleTabs.size - 1
        }
    }

    // Force recomposition of content when internalSelectedIndex changes
    val currentCategory = remember(internalSelectedIndex) {
        allDietCategoryPages.getOrNull(internalSelectedIndex)
    }

    // Debug logging
    LaunchedEffect(internalSelectedIndex, recentlySelectedTabs, selectedVisibleIndex) {
        Log.d(TAG, "=== State Update ===")
        Log.d(TAG, "internalSelectedIndex: $internalSelectedIndex")
        Log.d(TAG, "selectedVisibleIndex: $selectedVisibleIndex")
        Log.d(TAG, "selectedVisibleIndex in bounds: ${selectedVisibleIndex in visibleTabs.indices}")
        Log.d(TAG, "recentlySelectedTabs: $recentlySelectedTabs")
        Log.d(TAG, "visibleTabs size: ${visibleTabs.size}")
        visibleTabs.forEachIndexed { index, page ->
            val originalIndex = visibleToAllMap[index]
            Log.d(TAG, "visibleTabs[$index]: ${page.title} (original index: $originalIndex)")
        }
        Log.d(TAG, "Selected tab title: ${visibleTabs.getOrNull(selectedVisibleIndex)?.title}")
        Log.d(TAG, "Current category: ${currentCategory?.title}")
        Log.d(TAG, "==================")
    }

    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 12.dp, vertical = 0.dp)
            .background(
                color = MaterialTheme.customColors.orangeLight,
                shape = RoundedCornerShape(16.dp)
            )
            .clip(
                RoundedCornerShape(
                    bottomStart = 16.dp,
                    bottomEnd = 16.dp
                )
            )
            .padding(horizontal = 6.dp, vertical = 0.dp)
    ) {
        // Heading
        Text(
            text = "Atharv, still looking for healthy diet?",
            fontSize = 18.sp,
            fontWeight = FontWeight.Bold,
            color = MaterialTheme.customColors.white,
            modifier = Modifier
                .padding(top = 8.dp)
                .padding(horizontal = 6.dp)
        )

        // ScrollableTabRow
        ScrollableTabRow(
            selectedTabIndex = selectedVisibleIndex,
            containerColor = Color.Transparent,
            contentColor = MaterialTheme.customColors.black,
            edgePadding = 0.dp,
            indicator = { tabPositions ->
                if (selectedVisibleIndex in tabPositions.indices) {
                    TabRowDefaults.Indicator(
                        modifier = Modifier.tabIndicatorOffset(tabPositions[selectedVisibleIndex]),
                        height = 5.dp,
                        color = MaterialTheme.customColors.header
                    )
                }
            }
        ) {
            visibleTabs.forEachIndexed { index, dietCategoryPage ->
                val isSeeAllTab = dietCategoryPage is DietCategoryPage.SeeAll

                // Find original index for this visible tab
                val originalIndex = when {
                    index < initialVisibleCount -> index
                    isSeeAllTab -> -1
                    else -> visibleToAllMap[index] ?: -1
                }

                val isSelected = if (isSeeAllTab) {
                    false
                } else {
                    originalIndex == internalSelectedIndex
                }

                Tab(
                    selected = isSelected,
                    onClick = {
                        if (isSeeAllTab) {
                            // Navigate to See All page
                            navController?.navigate("category_diet_tabs_list/${internalSelectedIndex}") {
                                navController.currentBackStackEntry?.savedStateHandle?.set(
                                    "allDietCategories",
                                    allDietCategoryPages
                                )
                                navController.currentBackStackEntry?.savedStateHandle?.set(
                                    "currentDietMainTabIndex",
                                    internalSelectedIndex
                                )
                            }
                        } else {
                            // Regular tab click
                            if (originalIndex >= 0) {
                                Log.d(TAG, "Tab clicked: ${dietCategoryPage.title}, originalIndex: $originalIndex")

                                // Update internal selected index
                                internalSelectedIndex = originalIndex
                                onTabIndexChanged(originalIndex)
                                onCategorySelected(dietCategoryPage)

                                // IMPORTANT: Always add to recently selected if beyond initial count
                                if (originalIndex >= initialVisibleCount) {
                                    // Add to recently selected even if already there (to ensure it appears)
                                    recentlySelectedTabs = recentlySelectedTabs + originalIndex
                                    Log.d(TAG, "Added to recentlySelectedTabs on click: $originalIndex")
                                }
                            }
                        }
                    },
                    modifier = Modifier
                        .padding(horizontal = 2.dp, vertical = 5.dp)
                        .background(Color.Transparent)
                ) {
                    Column(
                        horizontalAlignment = Alignment.CenterHorizontally,
                        modifier = Modifier
                            .padding(vertical = 4.dp)
                            .width(80.dp)
                            .background(
                                color = MaterialTheme.customColors.white,
                                shape = RoundedCornerShape(15.dp)
                            )
                            .padding(horizontal = 5.dp, vertical = 5.dp)
                    ) {
                        Image(
                            painter = rememberAsyncImagePainter(dietCategoryPage.iconUrl),
                            contentDescription = dietCategoryPage.title,
                            modifier = Modifier
                                .width(65.dp)
                                .height(55.dp),
                            contentScale = ContentScale.FillBounds
                        )

                        Text(
                            text = dietCategoryPage.title,
                            fontSize = 15.sp,
                            fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Medium,
                            color = if (isSelected) {
                                MaterialTheme.customColors.header
                            } else {
                                MaterialTheme.customColors.black
                            },
                            maxLines = 2,
                            textAlign = TextAlign.Center,
                            overflow = TextOverflow.Ellipsis,
                            modifier = Modifier.padding(top = 2.dp)
                        )

                        // Show indicator for recently added tabs
                        if (!isSeeAllTab && originalIndex >= initialVisibleCount) {
                            Box(
                                modifier = Modifier
                                    .padding(top = 2.dp)
                                    .size(6.dp)
                                    .clip(CircleShape)
                                    .background(MaterialTheme.customColors.header.copy(alpha = 0.6f))
                            )
                        }
                    }
                }
            }
        }
    }

    // Content section - Using currentCategory directly for better reactivity
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .background(
                brush = Brush.verticalGradient(
                    colors = listOf(
                        Color(0xFFEDF6FF),
                        Color(0xFFFDFEFF)
                    )
                )
            )
    ) {
        // Log the current category for debugging
        LaunchedEffect(currentCategory) {
            Log.d(TAG, "Rendering content for category: ${currentCategory?.title} at index $internalSelectedIndex")
        }
        val restaurantViewModel: RestaurantViewModel = viewModel()
        when (currentCategory) {
            DietCategoryPage.Chicken -> ChickenDietPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.Salad -> SaladDietPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.Mutton -> MuttonDietPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.Kebabs -> KebabsDietPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.HealthySnacks -> HealthySnacksPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.LowCalorie -> LowCaloriePage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.Vegan -> VeganPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.ProteinRich -> ProteinRichPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.Dessert -> DessertPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.VegMeal -> VegMealPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.Bowl -> BowlPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.Sweets -> SweetsPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.Khichdi -> KhichdiPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.Sundae -> SundaePage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.Juice -> JuicePage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.Lassi -> LassiPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.CurdRice -> CurdRicePage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.Pudding -> PuddingPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.Custard -> CustardPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.Soup -> SoupDietPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.Brownie -> BrowniePage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.Waffles -> WafflesPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.ColdCoffee -> ColdCoffeePage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.GrilledChicken -> GrilledChickenDietPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.SteamedFish -> SteamedFishDietPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.QuinoaBowl -> QuinoaBowlDietPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.AvocadoToast -> AvocadoToastDietPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.GreenSmoothie -> GreenSmoothieDietPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.Oatmeal -> OatmealDietPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.GreekYogurt -> GreekYogurtDietPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.EggWhiteOmelette -> EggWhiteOmeletteDietPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.TunaSalad -> TunaSaladDietPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.LentilSoup -> LentilSoupDietPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.CottageCheese -> CottageCheeseDietPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.SproutsSalad -> SproutsSaladDietPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.BrownRiceBowl -> BrownRiceBowlDietPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.SteamedVeggies -> SteamedVeggiesDietPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.FruitBowl -> FruitBowlDietPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.DetoxWater -> DetoxWaterDietPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.HerbalTea -> HerbalTeaDietPage(restaurantViewModel = restaurantViewModel)
            DietCategoryPage.ProteinBar -> ProteinBarDietPage()
            DietCategoryPage.BoiledEggs -> BoiledEggsDietPage()
            DietCategoryPage.HummusPlate -> HummusPlateDietPage()
            DietCategoryPage.SushiRolls -> SushiRollsDietPage()
            DietCategoryPage.TofuStirFry -> TofuStirFryDietPage()
            DietCategoryPage.ChiaPudding -> ChiaPuddingDietPage()
            DietCategoryPage.MilletBowl -> MilletBowlDietPage()
            DietCategoryPage.SeeAll -> {
                // When "See All" is selected, show the grid view
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(200.dp),
                    contentAlignment = Alignment.Center
                ) {
                    Text(
                        text = "All categories view",
                        color = MaterialTheme.customColors.gray,
                        fontSize = 16.sp
                    )
                }
            }
            null -> {
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(200.dp),
                    contentAlignment = Alignment.Center
                ) {
                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                        Text(
                            text = "Select a diet category",
                            color = MaterialTheme.customColors.gray,
                            fontSize = 16.sp
                        )
                        Text(
                            text = "Current index: $internalSelectedIndex",
                            color = MaterialTheme.customColors.gray,
                            fontSize = 12.sp
                        )
                    }
                }
            }
        }

    }
}

